import json

# Search all keys and values in the JSON for exchange rate data
def search_json(data, path=''):
    if isinstance(data, dict):
        for key, value in data.items():
            search_json(value, f'{path}.{key}')
    elif isinstance(data, list):
        for i, item in enumerate(data):
            search_json(item, f'{path}[{i}]')
    elif isinstance(data, str):
        if 'exchange' in data.lower() or 'rate' in data.lower():
            print(f'{path}: {data[:200]}')

for fname in ['/app/resources/treasury_bulletin_1960_01.json', '/app/resources/treasury_bulletin_1960_02.json']:
    print(f'Searching {fname}:')
    with open(fname) as f:
        data = json.load(f)
        search_json(data)
    print('---')
